import { clamp, hasFinePointer, prefersReducedMotion } from "../utils/motion";

/**
 * Proximity magnification: the behavior behind the Holominimal sidebar, as a framework-free engine.
 *
 * Every item gets a weight `k` in [0, 1], written as a CSS custom property (default `--hm-k`); CSS turns it into scale,
 * offset and color. The current item (aria-current / data-active) is always 1. Other items rest small, fading with
 * their distance (in items) from the current one. A fine pointer near the container lifts items with a Gaussian
 * falloff along the main axis; keyboard focus lifts the focused item. Weights ease toward their targets with a
 * per-frame lerp, and the loop stops as soon as everything settles, so nothing runs while idle.
 *
 * Performance: no React state. One passive window listener; each frame reads every hit-rect first, then writes every
 * custom property (no layout thrash). Hit-testing uses each item's parent (the <li>), which never moves; the item
 * itself scales, so measuring it would feed back into the pointer distance (that was the jitter in the original).
 */
export type ProximityOptions = {
  /** Items inside the container. Default `[data-hm-proximity-item]`. */
  itemSelector?: string;
  /** Main axis the items are laid out along. Default `y` (a vertical list). */
  axis?: "x" | "y";
  /** Distance in px along the main axis over which the pointer magnifies an item (Gaussian sigma). Default 96. */
  reach?: number;
  /** Distance in px from the container's edge on the cross axis within which the pointer counts. Default 300. */
  range?: number;
  /** Which cross-axis edge `range` is measured from: `start` (left, or top for `axis: "x"`) or `end` (right, or bottom). Default `start`. */
  edge?: "start" | "end";
  /** Cross-axis inset in px before the falloff begins. Default 24. */
  inset?: number;
  /** Resting weight far from the current item. Default 0.1. */
  restBase?: number;
  /** Extra resting weight next to the current item. Default 0.3. */
  restSpread?: number;
  /** How many items the resting weight takes to fall off. Default 3. */
  restFalloff?: number;
  /** Ceiling for a non-current item (so the current one stays the largest). Default 0.92. */
  peak?: number;
  /** Lerp factor per frame (0..1); higher is snappier. Default 0.18. */
  smoothing?: number;
  /** Custom property to write. Default `--hm-k`. */
  property?: string;
  /** Measure each item itself (`self`, for table rows) or its parent (`parent`, the default, for items that scale). */
  hit?: "parent" | "self";
  /** Only count the pointer while it is over the container (plus `reach` on the main axis), for hover highlights. */
  bounded?: boolean;
};

const CURRENT = '[aria-current]:not([aria-current="false"]), [data-active]';

export function createProximity(container: HTMLElement, options: ProximityOptions = {}): () => void {
  const {
    itemSelector = "[data-hm-proximity-item]",
    axis = "y",
    reach = 96,
    range = 300,
    edge = "start",
    inset = 24,
    restBase = 0.1,
    restSpread = 0.3,
    restFalloff = 3,
    peak = 0.92,
    smoothing = 0.18,
    property = "--hm-k",
    hit = "parent",
    bounded = false,
  } = options;

  let items: HTMLElement[] = [];
  let cur: number[] = [];
  let active = -1;
  let pointer: { x: number; y: number } | null = null;
  let focused = -1;
  let raf = 0;
  let reduce = prefersReducedMotion(container);
  const fine = hasFinePointer();

  const collect = () => {
    const next = Array.from(container.querySelectorAll<HTMLElement>(itemSelector));
    // keep the eased value of items that survive (a list re-render should not snap every entry)
    cur = next.map((el) => {
      const prev = items.indexOf(el);
      return prev >= 0 ? (cur[prev] ?? 0) : Number.parseFloat(el.style.getPropertyValue(property)) || 0;
    });
    items = next;
    active = items.findIndex((el) => el.matches(CURRENT));
  };

  const rest = (i: number) =>
    active < 0 ? restBase + restSpread * 0.5 : restBase + restSpread * Math.exp(-Math.abs(i - active) / restFalloff);

  const paint = () => {
    // read phase: every rect before any write
    let near = 0;
    let centers: number[] | null = null;
    if (pointer && fine && !reduce) {
      const box = container.getBoundingClientRect();
      const cross =
        axis === "y"
          ? edge === "end"
            ? box.right - pointer.x
            : pointer.x - box.left
          : edge === "end"
            ? box.bottom - pointer.y
            : pointer.y - box.top;
      near = clamp(1 - Math.max(0, cross - inset) / range, 0, 1);
      if (bounded) {
        const mainPos = axis === "y" ? pointer.y : pointer.x;
        const crossPos = axis === "y" ? pointer.x : pointer.y;
        const [mainLo, mainHi] = axis === "y" ? [box.top, box.bottom] : [box.left, box.right];
        const [crossLo, crossHi] = axis === "y" ? [box.left, box.right] : [box.top, box.bottom];
        const inside =
          crossPos >= crossLo && crossPos <= crossHi && mainPos >= mainLo - reach && mainPos <= mainHi + reach;
        near = inside ? 1 : 0;
      }
      if (near > 0) {
        centers = items.map((el) => {
          const r = (hit === "self" ? el : (el.parentElement ?? el)).getBoundingClientRect();
          return axis === "y" ? r.top + r.height / 2 : r.left + r.width / 2;
        });
      }
    }
    // write phase
    let moving = false;
    for (let i = 0; i < items.length; i++) {
      let t: number;
      if (i === active) t = 1;
      else {
        t = rest(i);
        if (centers && pointer) {
          const d = (axis === "y" ? pointer.y : pointer.x) - (centers[i] ?? 0);
          t = Math.max(t, peak * Math.exp(-((d / reach) ** 2)) * near);
        }
        if (i === focused) t = Math.max(t, peak);
        t = Math.min(t, peak);
      }
      const prev = cur[i] ?? 0;
      const v = reduce ? t : prev + (t - prev) * smoothing;
      cur[i] = Math.abs(t - v) < 0.002 ? t : v;
      if (cur[i] !== t) moving = true;
      items[i]?.style.setProperty(property, (cur[i] ?? 0).toFixed(3));
    }
    raf = moving ? requestAnimationFrame(paint) : 0;
  };
  const kick = () => {
    if (!raf) raf = requestAnimationFrame(paint);
  };

  const onMove = (e: PointerEvent) => {
    if (e.pointerType !== "mouse" && e.pointerType !== "pen") return;
    pointer = { x: e.clientX, y: e.clientY };
    kick();
  };
  const onLeave = () => {
    pointer = null;
    kick();
  };
  const onFocusIn = (e: FocusEvent) => {
    focused = items.indexOf(e.target as HTMLElement);
    kick();
  };
  const onFocusOut = () => {
    focused = -1;
    kick();
  };
  const motionQuery = typeof matchMedia === "function" ? matchMedia("(prefers-reduced-motion: reduce)") : null;
  const onMotionChange = () => {
    reduce = prefersReducedMotion(container);
    kick();
  };
  // the current item changes on navigation, items come and go with the list: re-collect and re-target
  const observer =
    typeof MutationObserver === "function"
      ? new MutationObserver(() => {
          collect();
          reduce = prefersReducedMotion(container);
          kick();
        })
      : null;

  collect();
  if (fine) addEventListener("pointermove", onMove, { passive: true });
  document.documentElement.addEventListener("pointerleave", onLeave);
  container.addEventListener("focusin", onFocusIn);
  container.addEventListener("focusout", onFocusOut);
  motionQuery?.addEventListener("change", onMotionChange);
  observer?.observe(container, {
    subtree: true,
    childList: true,
    attributes: true,
    attributeFilter: ["aria-current", "data-active"],
  });
  // first frame snaps to the targets so server-rendered resting values never animate in from zero
  const wasReduce = reduce;
  reduce = true;
  paint();
  reduce = wasReduce;

  return () => {
    removeEventListener("pointermove", onMove);
    document.documentElement.removeEventListener("pointerleave", onLeave);
    container.removeEventListener("focusin", onFocusIn);
    container.removeEventListener("focusout", onFocusOut);
    motionQuery?.removeEventListener("change", onMotionChange);
    observer?.disconnect();
    cancelAnimationFrame(raf);
  };
}
